        return {"traceable": valid, "verified": valid,
            "score_context": {"severity_level": draft["factor_proposals"].get("severity_level"), "strategic_fit_level": draft["factor_proposals"].get("strategic_fit_level"), "complexity_level": draft["factor_proposals"].get("complexity_level"), "target_regions": ["US"], "region_counts": {"US": {"support": 2, "cohort": 3}}, "forecasts": [{"vehicle_line": "G60_G68", "region": "US", "year": 2030, "volume": 100, "source_reference": "sales-1"}], "target_vehicle_lines": ["G60"], "reference_volume": 200},
